  str_cn12_n41_levelname7 = "N5 - Jalan Yulin",
  str_cn12_n41_levelname8 = "N6 - Janji Dikhianati",
  str_cn12_n41_levelname9 = "N7 - Kehormatan yang Ditinggalkan",
  str_cn12_n41_levelname10 = "N8 - Usir Beast",
  str_cn12_n41_levelname11 = "N9 - Fate Rider",
  str_cn12_n41_levelname12 = "N10 - Jalur yang Terbagi",
  str_cn12_n41_levelname13 = "N11 - Banjir Air",
  str_cn12_n41_levelname14 = "N12 - Laut Lebih Tenang",
  str_cn12_n41_levelname15 = "ST3 - Festival Musim Semi",
  str_cn12_n41_levelname_desc1 = "—",
  str_cn12_n41_levelname_desc2 = "Anda menerima sambutan yang meriah, yang jelas menunjukkan bahwa penguasa Kerajaan Ji sangat menghargai Anda, namun perubahan kejadian...",
  str_cn12_n41_levelname_desc3 = "Dentuman kembang api bergema di jalanan; apa yang tampaknya seperti permainan anak-anak ternyata menjadi sesuatu yang lebih...",
  str_cn12_n41_levelname_desc4 = "Konflik muncul antara anak-anak dan seorang iblis kecil, tampaknya hal sepele sampai makhluk itu menjadi ganas...",
  str_cn12_n41_levelname_desc5 = "—",
  str_cn12_n41_levelname_desc6 = "Untuk mengungkap cara menenangkan fiendling yang gila, kamu dan Luo Song mulai mencari gadis yang pernah kamu temui sebelumnya...",
  str_cn12_n41_levelname_desc7 = "Dibimbing oleh kekuatan psikis Anda, kelompok ini perlahan mendekati sumber kekuatan yang merusak di kota—Yulin Street.",
  str_cn12_n41_levelname_desc8 = "Di dalam istana, transaksi meriam pantai antara Kerajaan Ji dan Kerajaan Ye menciptakan gelombang baru...",
  str_cn12_n41_levelname_desc9 = "Bersama-sama, Tuan Lin Guild dan Mu Yuebai mengungkapkan kepada Anda masa lalu antara Yoh dan keluarga Lin...",
  str_cn12_n41_levelname_desc10 = "Bersatu, warga ibu kota memutuskan untuk mengusir para fiendling sekali dan untuk selamanya. Dengan tongkat dan pentungan di tangan, mereka menghadapi para fiendling di jalanan.",
  str_cn12_n41_levelname_desc11 = "Dantang, mencoba menyelinap keluar dari istana, mendapati dirinya dikelilingi oleh banyak mata-mata, membuatnya tidak bisa melakukan gerakan apa pun...",
  str_cn12_n41_levelname_desc12 = "Anda mencapai teluk, dan meskipun diberi peringatan oleh Chen'ni, Anda dan Mu Yuebai tiba-tiba terengulf oleh kekuatan yang merusak.",
  str_cn12_n41_levelname_desc13 = "Luo Song dan Liqing bekerja sama untuk menangani fiendlings yang dipengaruhi oleh skema Fate Riders di dalam kota. Tapi tiba-tiba, langit menjadi gelap, dan gelombang besar menutupi langit...",
  str_cn12_n41_levelname_desc14 = "Kekuatan gelap yang mencoba mengendalikan Yoh akhirnya menunjukkan dirinya, karena ia tidak bisa menahan diri untuk bangkit dari kedalaman pikiran Yoh.",
  str_cn12_n41_levelname_desc15 = "—",
  str_cn12_n41_levelname16 = "H1 - Tempat Berlindung dari Bahaya",
  str_cn12_n41_levelname17 = "H2 - Melawan Fiendlings",
  str_cn12_n41_levelname18 = "H3 - Panggil Naga",
  str_cn12_n41_levelname19 = "H4 - Diberantas",
  str_cn12_n41_levelname20 = "EX1-1 - Berkhotbah",
  str_cn12_n41_levelname21 = "EX1-2 - Berkhotbah",
  str_cn12_n41_levelname22 = "EX2-1 - Fearless",
  str_cn12_n41_levelname23 = "EX2-2 - Fearless",
  str_cn12_n41_levelname24 = "EX3-1 - Permintaan Dikabulkan",
  str_cn12_n41_levelname25 = "EX3-2 - Permintaan Dikabulkan",
  str_cn12_n41_levelname26 = "EX3-3 - Permintaan Dikabulkan",
  str_cn12_n41_levelname27 = "EX1 - Berkhotbah",
  str_cn12_n41_levelname28 = "EX2 - Fearless",
  str_cn12_n41_levelname29 = "EX3 - Permintaan Dikabulkan",
  str_cn12_n41_levelname_desc16 = "Ombak bergulung, hujan turun deras. Penduduk kota panik, dekat dan jauh.",
  str_cn12_n41_levelname_desc17 = "Memecah ombak, menyembuhkan luka kejahatan. Gadis naga, bintang penuntun kita.",
  str_cn12_n41_levelname_desc18 = "Seribu tahun seperti nafas, seratus tahun seperti lagu. Dunia menjadi saksi kaburnya garis antara benar dan salah.",
  str_cn12_n41_levelname_desc19 = "Tahun-tahun berlalu, makhluk jahat masih bertahan dalam bayangan. Anugerah Gadis Naga melindungi semua arah, bersinar.",
  str_cn12_n41_levelname_desc20 = "EX1-1 - Khotbah: Earthfire",
  str_cn12_n41_levelname_desc21 = "EX1-2 - Khotbah: Skyfire",
  str_cn12_n41_levelname_desc22 = "EX2-1 - Fearless: Rainfall",
  str_cn12_n41_levelname_desc23 = "EX2-2 - Fearless: Hujan Lebat",
  str_cn12_n41_levelname_desc24 = "EX3-1 - Permintaan Dikabulkan: Jatuh Petir",
  str_cn12_n41_levelname_desc25 = "EX3-2 - Permintaan Dikabulkan: Balasan Petir",
  str_cn12_n41_levelname_desc26 = "EX3-3 - Permintaan Dikabulkan: Thundershock",
  str_cn12_n41_1600141_speak = "Kekayaan hanyalah sarana, bukan tujuan akhir. May semoga keberuntungan ini membantu Anda dalam mencapai keinginan hati Anda, Master Colossus.",
  str_cn12_n41_1602181_speak = "Undian beruntung Anda membawa kebahagiaan yang tak tertandingi bagi saya. Sejujurnya, kekayaan Anda, dalam satu cara, adalah kekayaan masa depan saya. Menantikan kunjungan Anda berikutnya!",
  str_cn12_n41_1601811_speak = "Kamu sedang berada di puncak kebugaranmu, teman muda. Tongkat keberuntungan ini berbicara tentang kekayaan, tetapi kekayaan, hubungan, peluang, dan ambisi tidak dapat dipisahkan—ini juga merupakan bukti kemampuanmu.",
  str_cn12_n41_1601211_speak = "Percaya bahwa satu batang tongkat keberuntungan bisa membawa kekayaan? Itu terlalu absurd! Eh, mungkin sihirnya ada pada keyakinan itu. Jadi, pastikan untuk menjaga semangatmu tetap tinggi!",
  str_cn12_n41_1601121_speak = "Keberuntungan sedang? Tidak buruk! Saat kamu mendapatkan uangnya, kunjungi Umbraton dan beli beberapa pakaian yang keren, tidak lagi pakaian polos itu.",
  str_cn12_n41_1500761_speak = "Karena mimpi adalah kebalikan dari kenyataan, mungkin hal yang sama berlaku untuk ramalan, bukan? Jangan khawatir; apakah kamu bangkrut atau tidak, aku selalu di sini di lautan dalam, menunggumu, Navigator.",
  str_cn12_n41_1300531_speak = "Hei, bos, tongkat keberuntunganmu cukup bagus! Keberuntungan sedang itu sempurna. Kamu pasti akan mendapatkan banyak uang tahun depan! Pastikan untuk sering mengunjungi tokoku!",
  str_cn12_n41_1500841_speak = "Kekayaan berarti kekuasaan di Umbraton, tetapi memamerkan terlalu banyak mengundang masalah. Keseimbangan adalah kunci, dan tongkat keberuntungan Anda tampak seperti tanda yang baik.",
  str_cn12_n41_1501871_speak = "Oh, Keberuntungan Kecil. Saya sudah mengambilnya dua kali, dan kamu baru saja mengambil yang terakhir. Haruskah kita mencari cara untuk membalikkan keberuntungan kita?",
  str_cn12_n41_1500331_speak = "Hmm... Keuntungan Kecil... Apakah mungkin pengeluaran harian kita masih terlalu tinggi? Tapi kenyataannya kita telah berhasil menjaga Colossus dalam keadaan baik dan masih memiliki surplus sudah cukup fantastis! Mari kita pertahankan kerja bagus ini juga di tahun depan!",
  str_cn12_n41_1300461_speak = [[
Mengharapkanmu sebuah keberuntungan, hidup yang begitu megah. Dalam hari-hari mendatang, biarkan kegembiraan berkembang.
Selamat datang kebaikan, dan semoga kesialan pergi.
Berikan hadiah berlimpah, dan semoga kesalahan tidak menemukanmu.
Keberuntungan kecil tetaplah keberuntungan! Pastikan untuk menambahkan lebih banyak dalam amplop merah untukku!]],
  str_cn12_n41_1600771_speak = "Kamu memiliki kekuatan untuk membentuk nasib dunia, jadi hasil ini bisa diperkirakan. Jangan khawatir; aku akan bersamamu setiap langkahnya.",
  str_cn12_n41_1602161_speak = "Di Longzhou, kami mengatakan pahlawan adalah \"Diberkati oleh Surga,\" atau \"Pemimpin yang Lahir, Ditakdirkan oleh Langit dan Bumi.\" Seperti yang kita bicarakan di Ruang Rekreasi, kamu persis seperti itu, selalu mengubah kesialan menjadi berkah, bukan?",
  str_cn12_n41_1601531_speak = "Sepertinya kamu siap untuk mencapai prestasi besar tahun ini. Ingatlah bahwa semakin tinggi kamu naik, semakin harus berhati-hati—Pohon besar menangkap lebih banyak angin, tahu kan? Dan jangan lupa untuk mencari bantuan dari rekan terpercaya kamu saat dibutuhkan.",
  str_cn12_n41_1601171_speak = "Haha, ekspresi wajahmu sudah mengatakan semuanya! Baguslah kalau generasi muda punya ambisi tinggi. Tapi ingat, selain pertempuran dan latihan, kesehatan juga penting. Mau coba sup kalengan?",
  str_cn12_n41_1601191_speak = "Visi besar... apa itu? Apakah tongkat keberuntungan ini berarti kamu akan lebih kuat melawan Eclipsite? Tapi hei, tongkatku berkata \"Keberuntungan Besar.\" Heehee, itu jauh lebih keren daripada milikmu, bukan?",
  str_cn12_n41_1600061_speak = "Hasil yang memuaskan—tidak begitu mengecewakan, tetapi cukup untuk menyalakan semangat juangmu untuk masa depan yang lebih cerah. Saya berharap saya memiliki peran dalam versi masa depanmu itu.",
  str_cn12_n41_1600021_speak = "Semua di dunia ini pada dasarnya hampa. Kesadaran seperti itu adalah yang membantu seseorang menembus batas-batasnya. May nasib kita adalah milik kita sendiri untuk diperintah.",
  str_cn12_n41_1601291_speak = "Sepertinya keberuntungan ada di pihakmu, rekan. Apa, masih belum puas? Setelah saya selesai dengan misi ini, saya akan melukis gambar Kemakmuran Besar yang lebih indah untukmu.",
  str_cn12_n41_1600641_speak = "Selamat, kamu mendapatkan yang sama denganku—Keberuntungan Kecil tetaplah keberuntungan, bukan? Kita pasti akan membalikkan keadaan tahun ini! Tunggu, kenapa kamu melakukan Namaste seperti itu?",
  str_cn12_n41_1600301_speak = "Sudah kukatakan padamu untuk tetap bersamaku, Nak. Tak ada yang bisa menentukan kesuksesanmu selain dirimu sendiri! Hiduplah untuk saat ini, dan jalani hidup sepenuhnya!",
  str_cn12_n41_1500551_speak = "Tongkat nasib hanya untuk bersenang-senang, jadi jangan tanya saya bagaimana cara bergadang semalaman. Bagaimana kalau fokus dulu untuk bugar, langkah demi langkah?",
  str_cn12_n41_1601881_speak = "Tongkatmu mengatakan Kemakmuran Besar, yang berarti keberuntungan pasti berpihak padamu. Tunggu, itu juga membaca jodohmu tepat di depanmu... tapi hanya kita berdua di sini—ramalan Li Tianxian adalah penipuan total!",
  str_cn12_n41_1602111_speak = "Tidak bisa percaya kehidupan cinta Anda begitu menjanjikan! \"Pasangan takdir Anda mungkin ada di antara teman-teman Anda\"? Hmm...membuat saya agak bersemangat untuk perjalanan kita berikutnya, sedikit saja!",
  str_cn12_n41_1601161_speak = "Kamu tampaknya menjadi lebih populer daripada saya akhir-akhir ini! Tapi hei, menjadi terlalu populer tidak selalu bagus, jadi hati-hati. Dan jika kamu perlu menjauh dari beberapa situasi, Steel Wing V2 baru saya siap untuk kamu gunakan!",
  str_cn12_n41_1601311_speak = "Selamat, Yang Mulia! Menemukan seseorang untuk bersama dan menjalani hidup bersama adalah sesuatu yang sangat mengharukan dan beruntung.",
  str_cn12_n41_1601261_speak = "Kisah cinta dalam fiksi selalu dimulai seperti mimpi, menyenangkan sepanjang waktu, dan memiliki akhir yang bahagia. Saya percaya kehidupan cinta Anda akan sama sempurnanya dengan kisah-kisah tersebut.",
  str_cn12_n41_1500991_speak = "Nilai yang kita berikan pada orang lain membuat kita ragu untuk mendekatinya, meragukan apakah kita bisa memilikinya... Tapi kadang-kadang kamu harus berani, mendekat, meraih, untuk bahagia, bukan?",
  str_cn12_n41_1600261_speak = "Apa arti dari semua ini? Semuanya kosong saja... Apa, kamu ingin berbagi keberuntungan baik ini denganku?... Tiba-tiba merasa aneh... Baiklah, katakan padaku tongkat keberuntungan mana yang kamu tarik.",
  str_cn12_n41_1601111_speak = "Tidak takut untuk mendekat dan menjalin hubungan dengan orang lain sudah merupakan berkah dan kebahagiaan yang besar... Bisakah aku juga menemukan kebahagiaan sederhana seperti itu?",
  str_cn12_n41_1602121_speak = "Teks pada tongkat keberuntungan, bahkan yang memiliki harapan di dalamnya, bisa ditafsirkan secara rasional! Tapi penelitian psikologi saya kurang... Waktunya pergi ke perpustakaan untuk mencari beberapa materi psikologi romansa... Oops, maaf, saya berpikir keras lagi!",
  str_cn12_n41_1601051_speak = "Setelah berkata bahwa aku masih belum cukup umur untuk hal ini, kakakku pergi dengan kunci inggrisnya. Bisa kamu beritahu aku jika kamu melihatnya? Terima kasih, kamu yang terbaik!",
  str_cn12_n41_1501831_speak = "Sebagai yang lebih tua di sini, saya mendapatkan tongkat nasib yang sama seperti kamu. Tapi hei, kamu harus lebih memikirkan tentang makanan yang baik dan tetap sehat! Lihat? Bahkan Tinytail setuju, mengibaskan ekornya dan semuanya.",
  str_cn12_n41_litianxian_speak1 = "Ah, kau datang! Baru-baru ini, saya menemukan satu set tongkat keberuntungan yang indah. Dikatakan bahwa keinginan seseorang akan terungkap oleh pesan di tongkat itu. Ingin mencoba keberuntungan hari ini?",
  str_cn12_n41_litianxian_speak2 = "Terima kasih atas patronase Anda! Semoga May semua harapanmu menjadi kenyataan! Silakan kembali di hari lain, dan kita bisa membahas keberuntungan bersama-sama!",
  str_cn12_n41_game_title_tip = "Silakan pilih keberuntungan yang ingin Anda terima.",
